import sys
import re
import json

def parse_expression(expr, env):
    # Parse and evaluate expression using provided environment
    try:
        # Replace key references with their values
        for key, value in env.items():
            expr = expr.replace(f"{key}", str(value))

        # Evaluate the expression using eval with safe context
        # We use eval with a restricted environment to avoid code injection
        # Since we only allow integers, operators, and previously defined keys,
        # we can safely evaluate the expression
        result = eval(expr, {"__builtins__": {}}, env)
        if isinstance(result, int):
            return result
        else:
            raise ValueError(f"Expression evaluated to non-integer: {result}")
    except Exception as e:
        raise ValueError(f"Error evaluating expression: {e}")

def main():
    if len(sys.argv) != 2:
        sys.exit(1)

    path = sys.argv[1]

    # Read the file
    try:
        with open(path, 'r', encoding='utf-8') as file:
            lines = file.readlines()
    except FileNotFoundError:
        sys.exit(1)

    # Environment to store key-value pairs
    env = {}

    # Process each line
    for line in lines:
        line = line.strip()
        if not line:
            continue

        # Match key = expr pattern
        match = re.match(r'^([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)$', line)
        if not match:
            continue

        key = match.group(1)
        expr = match.group(2)

        # Validate expression syntax
        # The expression should only contain integers, operators, and previously defined keys
        # We'll use a simple parser that checks for valid tokens
        try:
            # Evaluate the expression
            value = parse_expression(expr, env)
            env[key] = value
        except Exception as e:
            sys.exit(f"Error parsing line: {line} - {e}")

    # Output the result as JSON
    print(json.dumps(env, indent=None))

if __name__ == "__main__":
    main()

import json
import sys
import time
import random
import string

def generate_token():
    return ''.join(random.choices(string.ascii_letters + string.digits, k=32))

def compute_key(token):
    return hash(token) % (2**64)

def main():
    if len(sys.argv) != 3:
        print("Usage: python reset_tool.py issue EMAIL or python reset_tool.py verify TOKEN")
        sys.exit(1)

    command = sys.argv[1]
    arg = sys.argv[2]

    tokens_file = "tokens.json"

    # Read tokens.json if it exists, otherwise use empty object
    try:
        with open(tokens_file, 'r') as f:
            tokens = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        tokens = {}

    if command == "issue":
        if not arg or not isinstance(arg, str):
            print("Invalid email")
            sys.exit(1)

        token = generate_token()
        key = compute_key(token)
        tokens[arg] = {
            "email": arg,
            "expires_at": int(time.time()) + 3600
        }

        with open(tokens_file, 'w') as f:
            json.dump(tokens, f, indent=2)

        print(token)

    elif command == "verify":
        if not arg or not isinstance(arg, str):
            print("invalid")
            sys.exit(1)

        key = compute_key(arg)
        if str(key) in tokens:
            entry = tokens[str(key)]
            if entry["expires_at"] > int(time.time()):
                print(entry["email"])
                del tokens[str(key)]
                with open(tokens_file, 'w') as f:
                    json.dump(tokens, f, indent=2)
            else:
                print("invalid")
        else:
            print("invalid")

    else:
        print("Usage: python reset_tool.py issue EMAIL or python reset_tool.py verify TOKEN")
        sys.exit(1)

if __name__ == "__main__":
    main()

