import os
import sys
import subprocess
from cryptography.fernet import Fernet
import base64

def get_passphrase():
    passphrase = os.getenv('RUNNER_PASSPHRASE')
    if not passphrase or not passphrase.strip():
        sys.stderr.write("missing passphrase\n")
        sys.exit(2)
    return passphrase

def encrypt_text(text, passphrase):
    key = base64.urlsafe_b64encode(passphrase.encode())
    fernet = Fernet(key)
    encrypted_data = fernet.encrypt(text.encode('utf-8'))
    return encrypted_data

def decrypt_text(encrypted_data, passphrase):
    key = base64.urlsafe_b64encode(passphrase.encode())
    fernet = Fernet(key)
    try:
        decrypted_data = fernet.decrypt(encrypted_data)
        return decrypted_data.decode('utf-8')
    except Exception:
        return None

def main():
    passphrase = get_passphrase()
    args = sys.argv[1:]

    if len(args) == 0:
        sys.stderr.write("missing passphrase\n")
        sys.exit(2)

    if args[0] == 'encrypt':
        input_text = sys.stdin.read()
        encrypted = encrypt_text(input_text, passphrase)
        sys.stdout.buffer.write(encrypted)
        sys.stdout.buffer.flush()
        sys.exit(0)

    elif args[0] == 'run':
        try:
            encrypted_data = sys.stdin.read()
            decrypted_text = decrypt_text(encrypted_data.encode('utf-8'), passphrase)
            if decrypted_text is None:
                sys.stderr.write("cannot read\n")
                sys.exit(1)
            lines = decrypted_text.split('\n')
            for line in lines:
                if line.strip():
                    result = subprocess.run(line, shell=True, capture_output=True, text=True)
                    sys.stdout.write(result.stdout)
                    sys.stdout.write(result.stderr)
                    sys.stdout.write('\n')
        except Exception as e:
            sys.stderr.write("cannot read\n")
            sys.exit(1)
        sys.exit(0)

    else:
        sys.stderr.write("invalid command\n")
        sys.exit(1)

if __name__ == "__main__":
    main()

import sys

def load_expenses():
    filename = "expenses.state"
    entries = []
    try:
        with open(filename, 'r') as file:
            for line in file:
                line = line.strip()
                if line:
                    parts = line.split()
                    if len(parts) == 2:
                        amount, category = parts[0], parts[1]
                        entries.append((amount, category))
    except FileNotFoundError:
        pass
    return entries

def save_expenses(entries):
    filename = "expenses.state"
    with open(filename, 'w') as file:
        for amount, category in entries:
            file.write(f"{amount} {category}\n")

def main():
    entries = load_expenses()

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue

        parts = line.split()
        command = parts[0]

        if command == "add":
            if len(parts) == 3:
                amount, category = parts[1], parts[2]
                if len(amount) >= 3 and amount[2] == '.' and amount[0:amount.find('.')] and amount[amount.find('.')+1:].isdigit():
                    entries.append((amount, category))
                    save_expenses(entries)
        elif command == "list":
            for amount, category in entries:
                print(f"{amount} {category}")

if __name__ == "__main__":
    main()

