import sys
import os

def main():
    # Read the first line as the search term
    try:
        search_term = input().strip()
    except EOFError:
        sys.exit(1)

    # Output file
    log_file = "linereport.log"

    # Process each subsequent line as a file path
    for line in sys.stdin:
        path = line.strip()
        if not path:
            continue

        try:
            # Read the file as UTF-8 text
            with open(path, 'r', encoding='utf-8') as file:
                lines = file.readlines()
                count = 0
                for line_content in lines:
                    if search_term in line_content:
                        count += 1
                # Write OK line
                with open(log_file, 'a') as f:
                    f.write(f"OK {path} {count}\n")
        except Exception as e:
            # Write FAIL line with exception message
            with open(log_file, 'a') as f:
                f.write(f"FAIL {path} {str(e)}\n")

if __name__ == "__main__":
    main()

