import time

def copy_file(source_path, dest_path, queue):
    try:
        with open(source_path, 'rb') as src, open(dest_path, 'wb') as dst:
            dst.write(src.read())
        queue.put(True)
    except Exception as e:
        queue.put(False)

def main():
    if len(sys.argv) != 3:
        sys.exit(1)

    dest_dir = sys.argv[1]
    max_concurrent = int(sys.argv[2])

    if not os.path.exists(dest_dir):
        sys.exit(1)

    if max_concurrent < 1:
        sys.exit(1)

    input_queue = Queue()
    result_queue = Queue()
    completed_count = 0
    active_count = 0
    copy_threads = []

    # Read input until EOF
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        source_path, dest_name = line.split('\t')
        dest_path = os.path.join(dest_dir, dest_name)
        input_queue.put((source_path, dest_path))

    # Start copy operations
    def worker():
        nonlocal completed_count
        while True:
            try:
                source_path, dest_path = input_queue.get(timeout=1)
                if input_queue.empty():
                    break
                result_queue.put((source_path, dest_path))
                input_queue.task_done()
            except:
                break

    # Start worker threads
    for _ in range(max_concurrent):
        t = threading.Thread(target=worker)
        t.daemon = True
        t.start()
        copy_threads.append(t)

    # Process completed copies
    while True:
        try:
            result = result_queue.get(timeout=1)
            if result is None:
                break
            source_path, dest_path = result
            # Simulate copy completion
            completed_count += 1
            result_queue.task_done()
        except:
            break

    # Wait for all threads to finish
    for t in copy_threads:
        t.join()

    print(f"COPIED {completed_count}")

if __name__ == "__main__":
    main()

import sys
import re
import os

def main():
    if len(sys.argv) != 3:
        sys.exit(1)

    template_path = sys.argv[1]
    context_path = sys.argv[2]

    # Load context if it exists
    context_vars = {}
    if os.path.exists(context_path):
        with open(context_path, 'r', encoding='utf-8') as f:
            for line in f:
                line = line.strip()
                if line and '=' in line:
                    name, value_str = line.split('=', 1)
                    name = name.strip()
                    value = value_str.strip()
                    if value.isdigit():
                        context_vars[name] = int(value)

    # Parse and evaluate template
    with open(template_path, 'r', encoding='utf-8') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue

            # Check if line has format NAME = EXPR
            match = re.match(r'^\s*(\w+)\s*=\s*(.*)$', line)
            if match:
                name = match.group(1).strip()
                expr = match.group(2).strip()

                # Evaluate expression
                try:
                    # Replace variables in expression
                    expr = expr.replace(' ', '')
                    # Evaluate using current context
                    result = eval(expr, {"__builtins__": {}}, context_vars.copy())
                    if isinstance(result, int):
                        context_vars[name] = result
                except:
                    # If evaluation fails, skip this line
                    pass
            else:
                # Replace {{ ... }} with values
                line = re.sub(r'\{\{(.+?)\}\}', lambda m: str(context_vars.get(m.group(1).strip(), 0)), line)
                print(line)

    # Write updated context
    if context_path:
        with open(context_path, 'w', encoding='utf-8') as f:
            for name, value in sorted(context_vars.items()):
                f.write(f"{name}={value}\n")

