import sys
import xml.etree.ElementTree as ET
import subprocess
import threading
import queue
import signal
import os

def parse_config(config_path):
    tree = ET.parse(config_path)
    root = tree.getroot()
    pools = {}
    for pool_elem in root.findall('pool'):
        name = pool_elem.get('name')
        limit = int(pool_elem.get('limit'))
        commands = [cmd.text for cmd in pool_elem.findall('command')]
        pools[name] = {'limit': limit, 'commands': commands}
    return pools

def run_command(pool_name, command, output_queue):
    try:
        process = subprocess.Popen(
            command, 
            stdout=subprocess.PIPE, 
            stderr=subprocess.DEVNULL, 
            text=True, 
            bufsize=1
        )
        for line in process.stdout:
            output_queue.put(f"{pool_name}\t{line.rstrip()}")
        process.wait()
    except Exception as e:
        # In case of error, just ignore
        pass

def main():
    if len(sys.argv) != 2:
        sys.stderr.write("Usage: python pool_runner.py <config_file.xml>\n")
        sys.exit(1)

    config_path = sys.argv[1]
    pools = parse_config(config_path)

    # Global queue to store output lines
    output_queue = queue.Queue()

    # Global lock to prevent race conditions
    lock = threading.Lock()

    # List to hold running threads
    running_threads = []

    # Function to process a single command line
    def process_line(line):
        line = line.strip()
        if not line:
            return

        if line not in pools:
            return

        pool_data = pools[line]
        commands = pool_data['commands']
        limit = pool_data['limit']

        # Start at most 'limit' commands in parallel
        threads = []
        for i in range(0, len(commands), limit):
            batch = commands[i:i + limit]
            for cmd in batch:
                thread = threading.Thread(target=run_command, args=(line, cmd, output_queue))
                thread.start()
                threads.append(thread)

        # Wait for all commands in this batch to finish
        for thread in threads:
            thread.join()

    # Read stdin line by line
    try:
        while True:
            line = input().strip()
            if not line:
                break
            process_line(line)
    except EOFError:
        pass

    # Wait for any remaining output in the queue
    while not output_queue.empty():
        try:
            output = output_queue.get_nowait()
            print(output)
        except queue.Empty:
            break

if __name__ == "__main__":
    main()

import sys
import os
import re

def compute_expression(expression):
    try:
        # Remove spaces and evaluate the expression
        expr = re.sub(r'\s+', '', expression)
        return eval(expr, {"__builtins__": {}}, {})
    except:
        raise ValueError(f"Invalid expression: {expression}")

def hex_tag(value, secret):
    # Convert value to hex string, remove '0x' prefix, and ensure it's 16 characters
    value_hex = hex(value)[2:].zfill(16)
    # Combine value hex with secret and compute hash
    combined = value_hex + secret
    # Use SHA-256 to generate a fixed 16-character hex tag
    import hashlib
    hash_obj = hashlib.sha256(combined.encode('utf-8'))
    return hash_obj.hexdigest()[:16].lower()

def main():
    secret = os.environ.get('RENDERER_KEY')
    if not secret or secret == '':
        print("RENDERER_KEY is not set", file=sys.stderr)
        sys.exit(2)

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        try:
            value = compute_expression(line)
            tag = hex_tag(value, secret)
            print(f"{value}|{tag}")
        except Exception as e:
            print(f"Error evaluating expression: {e}", file=sys.stderr)
            sys.exit(1)

if __name__ == "__main__":
    main()

import hashlib
import os

def compute_hex_digest(file_path):
    """Compute the hexadecimal digest of a file's contents."""
    hash_md5 = hashlib.md5()
    try:
        with open(file_path, 'rb') as f:
            for chunk in iter(lambda: f.read(4096), b""):
                hash_md5.update(chunk)
        return hash_md5.hexdigest()
    except Exception:
        return None

def main():
    input_file = "input_paths.txt"
    output_file = "digest.log"

    processed_count = 0
    error_count = 0

    # Read paths from input_paths.txt
    with open(input_file, 'r') as f:
        paths = [line.strip() for line in f if line.strip()]

    # Write to digest.log
    with open(output_file, 'w') as log:
        for path in paths:
            if os.path.exists(path) and os.path.isfile(path):
                digest = compute_hex_digest(path)
                if digest:
                    log.write(f"{path}\t{digest}\n")
                    processed_count += 1
                else:
                    log.write(f"ERROR {path}\n")
                    error_count += 1
            else:
                log.write(f"ERROR {path}\n")
                error_count += 1

    # Final summary line
    log.write(f"Completed: {processed_count} processed, {error_count} errors")

if __name__ == "__main__":
    main()

import sys
import json
import os

def main():
    if len(sys.argv) != 3:
        return

    template_path = sys.argv[1]
    data_path = sys.argv[2]

    try:
        with open(template_path, 'r', encoding='utf-8') as f:
            template = f.read()
    except Exception:
        return

    try:
        with open(data_path, 'r', encoding='utf-8') as f:
            data = json.load(f)
    except Exception:
        print("error: cannot read data", file=sys.stderr)
        sys.exit(1)

    if not isinstance(data, dict):
        print("error: cannot read data", file=sys.stderr)
        sys.exit(1)

    result = template
    keys_to_replace = []

    # Find all {{key}} patterns
    start = 0
    while True:
        idx = result.find('{{', start)
        if idx == -1:
            break
        end = result.find('}}', idx + 2)
        if end == -1:
            break
        key = result[idx + 2:end]
        # Validate key: one or more characters that are not { or }
        if not key or any(c in key for c in '{'}):
            start = end + 2
            continue
        keys_to_replace.append(key)
        start = end + 2

    # Replace each {{key}} with the value from data, or empty string if key is missing
    for key in keys_to_replace:
        if key in data:
            result = result.replace(f"{{{{{{{key}}}}}}}", data[key])
        else:
            result = result.replace(f"{{{{{{{key}}}}}}}", "")
            print(f"missing key: {key}", file=sys.stderr)

    print(result)

if __name__ == "__main__":
    main()

import sys
import json
import re

def evaluate_expression(expr, json_data):
    # Remove leading/trailing whitespace and strip inner whitespace
    expr = expr.strip()
    # Remove whitespace around {{ and }}
    expr = re.sub(r'\s*{{\s*', '{{', expr)
    expr = re.sub(r'\s*}}\s*', '}}', expr)

    # Extract the expression part between {{ and }}
    match = re.search(r'{{\s*(.+?)\s*}}', expr)
    if not match:
        return None

    expression = match.group(1).strip()

    # Replace variable names in expression with their values from JSON
    # Variables are keys in the JSON object
    try:
        # Evaluate the expression using the JSON data
        # We need to handle variable names and arithmetic operations
        # Replace variable names with their values
        for var_name in json_data.keys():
            expression = expression.replace(f'{{{var_name}}}', str(json_data[var_name]))

        # Evaluate the expression
        result = eval(expression)

        # Check if result is an integer
        if not isinstance(result, int):
            return None

        return result

    except Exception as e:
        return None

def main():
    if len(sys.argv) != 3:
        sys.exit(1)

    template_path = sys.argv[1]
    json_path = sys.argv[2]

    # Read JSON file
    try:
        with open(json_path, 'r') as f:
            json_data = json.load(f)
    except Exception as e:
        sys.exit(1)

    # Ensure JSON data is a dictionary with integer values
    for key, value in json_data.items():
        if not isinstance(value, int):
            sys.exit(1)

    # Create errors.log file if it doesn't exist
    errors_log = "errors.log"
    try:
        with open(errors_log, 'w') as f:
            pass  # Create empty file
    except Exception as e:
        sys.exit(1)

    # Read template file line by line
    line_number = 1
    try:
        with open(template_path, 'r') as f:
            for line in f:
                line = line.strip()
                if not line:
                    print(line)
                    line_number += 1
                    continue

                # Check for placeholder
                match = re.search(r'{{\s*(.+?)\s*}}', line)
                if match:
                    expression = match.group(1).strip()
                    result = evaluate_expression(expression, json_data)
                    if result is None:
                        error_msg = f"Line {line_number}: "
                        if expression in json_data:
                            error_msg += f"expression did not evaluate to an integer"
                        else:
                            error_msg += f"missing variable {expression}"
                        with open(errors_log, 'a') as f:
                            f.write(error_msg + '\n')
                    else:
                        # Replace the placeholder with the evaluated result
                        new_line = line.replace(f'{{{{ {expression} }}}}', str(result))
                        print(new_line)
                else:
                    # No placeholder, print unchanged
                    print(line)

                line_number += 1

    except Exception as e:
        sys.exit(1)

if __name__ == "__main__":
    main()

import sys
import subprocess
import re

def evaluate_expression(expr):
    try:
        # Replace any whitespace within the expression with a single space
        expr = re.sub(r'\s+', ' ', expr)
        # Evaluate the arithmetic expression
        result = eval(expr)
        return str(result)
    except Exception as e:
        return ""

def main():
    if len(sys.argv) != 2:
        sys.exit(1)

    templates_file = sys.argv[1]

    try:
        with open(templates_file, 'r', encoding='utf-8') as file:
            lines = file.readlines()
    except FileNotFoundError:
        sys.exit(1)

    for line in lines:
        line = line.strip()
        if not line:
            continue

        # Replace {{...}} with evaluated expression
        match = re.finditer(r'\{\{([^}]+)\}\}', line)
        for match_obj in match:
            expr = match_obj.group(1)
            evaluated = evaluate_expression(expr)
            line = line.replace(f"{{{{{{{expr}}}}}}}", evaluated)

        # Run the command through the shell and capture output
        try:
            result = subprocess.run(line, shell=True, capture_output=True, text=True, timeout=30)
            print(result.stdout)
        except subprocess.TimeoutExpired:
            print("")
        except Exception as e:
            print("")

