import sys
import json
import subprocess
import shlex

def runchecks(json_file_path):
    with open(json_file_path, 'r') as file:
        data = json.load(file)

    for item in data:
        command = item['command']
        expect = item['expect']

        try:
            # Run the command and capture stdout
            result = subprocess.run(
                shlex.split(command),
                capture_output=True,
                text=True,
                check=False
            )
            out = result.stdout.strip()
        except Exception as e:
            out = ""

        # Evaluate the expect expression with 'out' bound to the captured output
        try:
            expression_result = eval(expect, {"out": out})
            if expression_result:
                print("PASS")
            else:
                print("FAIL")
        except Exception as e:
            print("FAIL")

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python runchecks.py <path_to_json_file>")
        sys.exit(1)
    runchecks(sys.argv[1])

import sys
import json
import requests
import os
from datetime import datetime
import subprocess

def main(config_path):
    # Read config file
    try:
        with open(config_path, 'r') as f:
            config = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        print("ERROR")
        sys.exit(1)

    # Validate required fields
    required_fields = ['url', 'command', 'state_path', 'log_path']
    for field in required_fields:
        if field not in config or not isinstance(config[field], str):
            print("ERROR")
            sys.exit(1)

    url = config['url']
    command = config['command']
    state_path = config['state_path']
    log_path = config['log_path']

    # Send HTTP GET request
    try:
        response = requests.get(url, timeout=10)
        if response.status_code != 200:
            log_entry = create_log_entry("ERROR", f"HTTP status {response.status_code}")
            print(log_entry)
            if not os.path.exists(log_path) or not os.path.isfile(log_path):
                sys.exit(1)
            try:
                with open(log_path, 'a') as f:
                    f.write(log_entry + '\n')
            except:
                sys.exit(1)
            sys.exit(1)

        response_json = response.json()
        if not isinstance(response_json, dict) or 'build_id' not in response_json or not isinstance(response_json['build_id'], str):
            log_entry = create_log_entry("ERROR", "Response body is not a valid JSON with build_id field")
            print(log_entry)
            if not os.path.exists(log_path) or not os.path.isfile(log_path):
                sys.exit(1)
            try:
                with open(log_path, 'a') as f:
                    f.write(log_entry + '\n')
            except:
                sys.exit(1)
            sys.exit(1)

        build_id = response_json['build_id']

    except requests.RequestException as e:
        log_entry = create_log_entry("ERROR", f"Request failed: {str(e)}")
        print(log_entry)
        if not os.path.exists(log_path) or not os.path.isfile(log_path):
            sys.exit(1)
        try:
            with open(log_path, 'a') as f:
                f.write(log_entry + '\n')
        except:
            sys.exit(1)
        sys.exit(1)

    # Read state_path
    try:
        if os.path.exists(state_path):
            with open(state_path, 'r') as f:
                stored_build_id = f.read().strip()
        else:
            stored_build_id = None
    except Exception as e:
        log_entry = create_log_entry("ERROR", f"Failed to read state_path: {str(e)}")
        print(log_entry)
        if not os.path.exists(log_path) or not os.path.isfile(log_path):
            sys.exit(1)
        try:
            with open(log_path, 'a') as f:
                f.write(log_entry + '\n')
        except:
            sys.exit(1)
        sys.exit(1)

    # Run command if needed
    if stored_build_id != build_id:
        try:
            result = subprocess.run(command, shell=True, capture_output=True, text=True)
            if result.returncode != 0:
                log_entry = create_log_entry("ERROR", f"Command failed with exit code {result.returncode}")
                print(log_entry)
                if not os.path.exists(log_path) or not os.path.isfile(log_path):
                    sys.exit(1)
                try:
                    with open(log_path, 'a') as f:
                        f.write(log_entry + '\n')
                except:
                    sys.exit(1)
                sys.exit(1)
            # Write build_id to state_path
            with open(state_path, 'w') as f:
                f.write(build_id)
        except Exception as e:
            log_entry = create_log_entry("ERROR", f"Command execution failed: {str(e)}")
            print(log_entry)
            if not os.path.exists(log_path) or not os.path.isfile(log_path):
                sys.exit(1)
            try:
                with open(log_path, 'a') as f:
                    f.write(log_entry + '\n')
            except:
                sys.exit(1)
            sys.exit(1)
    else:
        # Command did not run
        pass

    # Create log entry
    timestamp = datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ')
    if stored_build_id is None:
        tag = "CHANGED"
        message = f"old=none new={build_id}"
    else:
        tag = "SAME"
        message = f"build_id={build_id}"

    log_entry = f"{timestamp} {tag} {message}"
    print(log_entry)

    # Write to log_path
    try:
        with open(log_path, 'a') as f:
            f.write(log_entry + '\n')
    except Exception as e:
        print(log_entry)
        sys.exit(1)

def create_log_entry(tag, message):
    timestamp = datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ')
    return f"{timestamp} {tag} {message}"

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("ERROR")
        sys.exit(1)
    config_path = sys.argv[1]
    main(config_path)

import sys
import os
import requests
from concurrent.futures import ThreadPoolExecutor, as_completed
import threading

def download_url(url, n):
    try:
        response = requests.get(url, timeout=30)
        if response.status_code // 100 == 2:
            filename = f"{n}.dat"
            with open(filename, 'wb') as f:
                f.write(response.content)
            return filename, response.status_code
        else:
            return None, response.status_code
    except Exception:
        return None, -1

def run_command(filename, n, command):
    try:
        # Run the command with the filename as the last argument
        result = os.system(f"{command} {filename}")
        return result
    except Exception:
        return -1

def main():
    if len(sys.argv) != 3:
        sys.exit(1)

    urls_file = sys.argv[1]
    command = sys.argv[2]

    urls = []
    with open(urls_file, 'r') as f:
        for line in f:
            line = line.strip()
            if line:
                urls.append(line)

    if not urls:
        sys.exit(0)

    results = []
    with ThreadPoolExecutor(max_workers=3) as executor:
        future_to_url = {
            executor.submit(download_url, url, i + 1): i + 1
            for i, url in enumerate(urls)
        }

        for future in as_completed(future_to_url):
            n = future_to_url[future]
            try:
                result, status_code = future.result()
                if result is not None:
                    # Run command if status is 2xx
                    exit_code = -1
                    try:
                        exit_code = run_command(result, n, command)
                    except Exception:
                        exit_code = -1
                    results.append(f"{n} {exit_code}")
                else:
                    results.append(f"{n} ERROR")
            except Exception as e:
                results.append(f"{n} ERROR")

    # Print results
    for result in results:
        print(result)

    sys.exit(0)

if __name__ == "__main__":
    main()

import sys
import json
import subprocess
import requests

def main():
    if len(sys.argv) != 3:
        sys.stderr.write("Usage: python run_pending.py <base_url> <token_file_path>\n")
        sys.exit(2)

    base_url = sys.argv[1]
    token_file_path = sys.argv[2]

    try:
        with open(token_file_path, 'r') as f:
            token = f.read().strip()
    except Exception as e:
        sys.stderr.write("Error reading token file: {}\n".format(str(e)))
        sys.exit(2)

    try:
        response = requests.get(f"{base_url}/pending", headers={"Authorization": f"Bearer {token}"})
        if response.status_code != 200:
            sys.stderr.write("HTTP request failed with status {}\n".format(response.status_code))
            sys.exit(2)

        data = response.json()
        if not isinstance(data, list):
            sys.stderr.write("Response body is not a JSON array\n")
            sys.exit(2)

        log_file = "run.log"
        with open(log_file, 'a') as f_log:
            for item in data:
                if not isinstance(item, dict) or "id" not in item or "cmd" not in item:
                    sys.stderr.write("Invalid command entry in response\n")
                    sys.exit(2)

                cmd = item["cmd"]
                try:
                    result = subprocess.run(cmd, shell=True, capture_output=True, text=True)
                    exit_code = result.returncode

                    log_entry = {"id": item["id"], "exit_code": exit_code}
                    f_log.write(json.dumps(log_entry) + "\n")
                    f_log.flush()

                    if exit_code != 0:
                        sys.exit(1)
                except Exception as e:
                    sys.stderr.write("Error executing command: {}\n".format(str(e)))
                    sys.exit(1)

        sys.exit(0)
    except Exception as e:
        sys.stderr.write("Error processing response: {}\n".format(str(e)))
        sys.exit(2)

if __name__ == "__main__":
    main()

import sys
import json
import subprocess
import re
from pathlib import Path
from concurrent.futures import ProcessPoolExecutor, as_completed
from typing import List, Dict, Any

def evaluate_expression(expr: str) -> int:
    # Replace all spaces and split by * first (since * has higher precedence)
    # Then evaluate each part with + operations
    # First, split by * and evaluate each part
    parts = re.split(r'(\*|\+)', expr)
    # Group the parts by operator
    tokens = []
    i = 0
    while i < len(parts):
        if parts[i] == '*':
            tokens.append(('*', parts[i+1]))
            i += 2
        else:
            tokens.append((parts[i], ''))
            i += 1

    # Evaluate multiplication first
    result = 0
    current_product = 1
    current_addition = 0
    i = 0
    while i < len(tokens):
        if tokens[i][0] == '*':
            # Multiply the next value
            if i + 1 < len(tokens):
                next_val = int(tokens[i+1][0]) if tokens[i+1][0].isdigit() else 0
                current_product *= next_val
                i += 2
            else:
                i += 1
        else:
            # It's a number or a + operator
            if tokens[i][0].isdigit():
                if current_product > 0:
                    current_addition += current_product
                current_product = 1
                current_addition += int(tokens[i][0])
            elif tokens[i][0] == '+':
                current_addition += current_product
                current_product = 1
            i += 1

    return current_addition + current_product

def replace_placeholders(command: str, expr_values: Dict[str, int]) -> str:
    # Replace {{expr}} with the evaluated value of expr
    result = command
    for key, value in expr_values.items():
        result = result.replace(f"{{{{{{{key}}}}}}}", str(value))
    return result

def run_command(command: str) -> Dict[str, Any]:
    try:
        # Run the command and capture output and error
        result = subprocess.run(
            command,
            shell=True,
            capture_output=True,
            text=True,
            timeout=30
        )
        return {
            "command": command,
            "output": result.stdout + result.stderr,
            "exit_code": result.returncode
        }
    except subprocess.TimeoutExpired:
        return {
            "command": command,
            "output": "Command timed out",
            "exit_code": -1
        }
    except Exception as e:
        return {
            "command": command,
            "output": f"Error: {str(e)}",
            "exit_code": -1
        }

def main():
    if len(sys.argv) < 2:
        print(json.dumps({"error": "Missing file path"}))
        sys.exit(1)

    file_path = sys.argv[1]
    concurrency = 1

    # Parse concurrency argument
    i = 2
    while i < len(sys.argv):
        if sys.argv[i] == '--concurrency':
            if i + 1 < len(sys.argv):
                try:
                    concurrency = int(sys.argv[i + 1])
                    if concurrency <= 0:
                        concurrency = 1
                except ValueError:
                    concurrency = 1
                i += 2
            else:
                i += 1
        else:
            i += 1

    # Read the file
    try:
        with open(file_path, 'r') as f:
            lines = f.readlines()
    except FileNotFoundError:
        print(json.dumps({"error": f"File not found: {file_path}"}))
        sys.exit(1)

    # Process each line
    commands = []
    for line in lines:
        line = line.strip()
        if not line:
            continue
        # Extract expressions like {{expr}} and evaluate them
        # We'll use a simple approach: replace each {{expr}} with the evaluated value
        # We need to evaluate expressions with * before +
        # We'll use a simple parser that handles only + and * with * having higher precedence
        # First, extract all expressions
        expr_matches = re.findall(r'\{\{(\w+)\}\}', line)
        expr_values = {}
        for expr in expr_matches:
            # Evaluate the expression
            try:
                # Simple evaluation: split by * and then by +
                # First, split by * and evaluate each part
                parts = re.split(r'(\*|\+)', expr)
                # Group the parts
                tokens = []
                i = 0
                while i < len(parts):
                    if parts[i] == '*':
                        tokens.append(('*', parts[i+1]))
                        i += 2
                    else:
                        tokens.append((parts[i], ''))
                        i += 1

                # Evaluate multiplication first
                current_product = 1
                current_sum = 0
                i = 0
                while i < len(tokens):
                    if tokens[i][0] == '*':
                        if i + 1 < len(tokens):
                            next_val = int(tokens[i+1][0]) if tokens[i+1][0].isdigit() else 0
                            current_product *= next_val
                            i += 2
                        else:
                            i += 1
                    else:
                        if tokens[i][0].isdigit():
                            current_sum += int(tokens[i][0])
                        i += 1

                expr_values[expr] = current_sum + current_product
            except Exception as e:
                expr_values[expr] = 0

        # Replace placeholders in the command
        processed_command = replace_placeholders(line, expr_values)
        commands.append(processed_command)

    # Run commands with concurrency
    results = []
    with ProcessPoolExecutor(max_workers=concurrency) as executor:
        future_to_command = {executor.submit(run_command, cmd): cmd for cmd in commands}
        for future in as_completed(future_to_command):
            result = future.result()
            results.append(result)

    # Output JSON objects
    for result in results:
        print(json.dumps(result))

