def get_file_size(path):
    try:
        return os.path.getsize(path)
    except (OSError, IOError):
        return None

def load_cache():
    cache_file = '.stats_cache'
    if os.path.exists(cache_file):
        cache = {}
        with open(cache_file, 'r') as f:
            for line in f:
                line = line.strip()
                if line:
                    parts = line.split('\t')
                    if len(parts) == 2:
                        path, size = parts[0], parts[1]
                        cache[path] = int(size)
        return cache
    return {}

def save_cache(cache):
    cache_file = '.stats_cache'
    with open(cache_file, 'w') as f:
        for path in sorted(cache.keys()):
            f.write(f"{path}\t{cache[path]}\n")

def main():
    cache = load_cache()
    paths = []
    for line in sys.stdin:
        line = line.strip()
        if line:
            paths.append(line)

    # Process paths in groups of up to 4
    groups = [paths[i:i+4] for i in range(0, len(paths), 4)]

    for group in groups:
        for path in group:
            if path in cache:
                print(f"{path}\t{cache[path]}")
            else:
                size = get_file_size(path)
                if size is not None:
                    cache[path] = size
                    print(f"{path}\t{size}")
                else:
                    print(f"{path}\tERROR")

    # Save the updated cache
