import sys
import time
import requests
from urllib.parse import urlparse

def main():
    if len(sys.argv) != 2:
        print("Usage: python fetch.py urls.txt")
        return

    urls_file = sys.argv[1]
    tokens_file = "tokens.txt"

    urls = []
    with open(urls_file, 'r') as f:
        for line in f:
            line = line.strip()
            if line:
                urls.append(line)

    # Read tokens
    tokens = {}
    with open(tokens_file, 'r') as f:
        for line in f:
            line = line.strip()
            if line:
                parts = line.split('\t')
                if len(parts) == 2:
                    hostname, token = parts[0], parts[1]
                    tokens[hostname] = token

    # Process each URL
    for url in urls:
        try:
            # Extract hostname
            parsed = urlparse(url)
            hostname = parsed.netloc

            if hostname not in tokens:
                print(f"DENIED {url}")
                continue

            token = tokens[hostname]

            # Send HTTP GET request
            start_time = time.time()
            headers = {"Authorization": f"Bearer {token}"}
            response = requests.get(url, headers=headers, timeout=5)

            if time.time() - start_time < 5:
                print(f"{response.status_code} {url}")
            else:
                print(f"ERROR {url}")

        except requests.exceptions.Timeout:
            print(f"ERROR {url}")
        except requests.exceptions.RequestException as e:
            print(f"ERROR {url}")

        # Wait 0.7 seconds before next request (except for the first one)
        if url != urls[0]:
            time.sleep(0.7)

