import sys
import re
import xml.etree.ElementTree as ET

def parse_expression(expr, variables):
    # Replace variable names with their values
    for var_name, var_value in variables.items():
        expr = expr.replace(var_name, str(var_value))

    # Evaluate the expression
    try:
        # Replace operators with Python-compatible ones
        # Handle division by zero and invalid expressions
        result = eval(expr, {"__builtins__": {}}, {})
        return result
    except ZeroDivisionError:
        raise ValueError("Division by zero")
    except Exception as e:
        raise ValueError(f"Invalid expression: {str(e)}")

def main():
    if len(sys.argv) != 2:
        sys.exit(1)

    xml_path = sys.argv[1]

    # Parse XML file
    try:
        tree = ET.parse(xml_path)
        root = tree.getroot()
    except ET.ParseError as e:
        sys.exit(1)
    except FileNotFoundError:
        sys.exit(1)

    # Read variable values from stdin
    variables = {}
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        match = re.match(r'^(\w+)=(\S+)$', line)
        if match:
            var_name = match.group(1)
            var_value = float(match.group(2))
            variables[var_name] = var_value

    # Process each field in order
    for field in root.findall('field'):
        name = field.get('name')
        expr = field.text.strip()
        if not expr:
            continue
        try:
            result = parse_expression(expr, variables)
            print(f"{name}={result}")
        except ValueError as e:
            sys.exit(1)

