import hashlib
import sys
import time
import os

def get_digest(algorithm, data):
    """Compute the hexadecimal digest of data using the specified algorithm."""
    if algorithm == 'md5':
        return hashlib.md5(data).hexdigest()
    elif algorithm == 'sha1':
        return hashlib.sha1(data).hexdigest()
    elif algorithm == 'sha224':
        return hashlib.sha224(data).hexdigest()
    elif algorithm == 'sha256':
        return hashlib.sha256(data).hexdigest()
    elif algorithm == 'sha384':
        return hashlib.sha384(data).hexdigest()
    elif algorithm == 'sha512':
        return hashlib.sha512(data).hexdigest()
    else:
        raise ValueError(f"Unsupported digest algorithm: {algorithm}")

def main():
    # Read the first line (digest algorithm)
    algorithm_line = sys.stdin.readline().strip()
    if not algorithm_line:
        return

    algorithm = algorithm_line

    # List to store the lines to write to manifest.txt
    manifest_lines = []

    # Process each remaining line
    for line in sys.stdin:
        path = line.strip()
        if not path:
            continue

        # Wait 0.2 seconds
        time.sleep(0.2)

        # Read the file's bytes
        try:
            with open(path, 'rb') as f:
                file_data = f.read()
        except FileNotFoundError:
            continue  # Skip if file not found

        # Compute the digest
        digest = get_digest(algorithm, file_data)

        # Create a line for the manifest
        manifest_line = f"{digest} {path}"
        manifest_lines.append(manifest_line)

    # Write to manifest.txt
    with open('manifest.txt', 'w') as f:
        for line in manifest_lines:
            f.write(line + '\n')

    # Print the number of lines written
    print(len(manifest_lines))

