def read_cache_file(cache_path):
    rows = []
    if os.path.exists(cache_path):
        with open(cache_path, 'r') as f:
            for line in f:
                fields = line.strip().split('\t')
                rows.append(fields)
    return rows

def write_cache_file(cache_path, rows):
    with open(cache_path, 'w') as f:
        for row in rows:
            f.write('\t'.join(row) + '\n')

def execute_query(database_path, table_name):
    conn = sqlite3.connect(database_path)
    cursor = conn.cursor()
    cursor.execute(f"SELECT * FROM {table_name}")
    columns = [description[0] for description in cursor.description]
    rows = cursor.fetchall()
    conn.close()

    result_rows = []
    for row in rows:
        result_row = []
        for field in row:
            if field is None:
                result_row.append("")
            else:
                result_row.append(str(field))
        result_rows.append(result_row)

    return result_rows

def main():
    if len(sys.argv) != 3:
        sys.exit(1)

    xml_path = sys.argv[1]
    cache_path = sys.argv[2]

    # Parse XML configuration
    try:
        tree = ET.parse(xml_path)
        root = tree.getroot()
        database_name = root.find('database').text
        table_name = root.find('table').text
    except ET.ParseError as e:
        sys.exit(1)

    # Get absolute path to database file
    xml_dir = os.path.dirname(xml_path)
    database_path = os.path.join(xml_dir, database_name)

    # Read cache file if it exists
    cache_rows = read_cache_file(cache_path)

    # If cache exists, print rows
    if cache_rows:
        for row in cache_rows:
            print('\t'.join(row))
    else:
        # Cache doesn't exist, run query and write to cache
