import re

def evaluate_expr(expr, vars_dict):
    try:
        # Replace variable names with their values
        for var_name, var_value in vars_dict.items():
            expr = expr.replace(f"{{{var_name}}}", str(var_value))

        # Evaluate the expression using eval with safe parsing
        # We need to ensure only allowed operations and integers are used
        # Since the input is restricted to +, -, *, integers, and parentheses
        # We can safely evaluate
        result = eval(expr)
        return result
    except Exception as e:
        raise ValueError(f"Error evaluating expression: {str(e)}")

def replace_placeholders(template, vars_dict):
    result = {}
    for key, value in template.items():
        if isinstance(value, str) and value.startswith('{{') and value.endswith('}}'):
            expr = value[2:-2]
            try:
                value_eval = evaluate_expr(expr, vars_dict)
                result[key] = value_eval
                print(f"placeholder: {expr} = {value_eval}", file=sys.stderr)
            except Exception as e:
                print(f"error: {str(e)}", file=sys.stderr)
                return None
        else:
            result[key] = value
    return result

