import sys
import json
import time
import os
from urllib.request import urlopen
from urllib.error import URLError, HTTPError

def main():
    if len(sys.argv) != 3:
        sys.exit(1)

    urls_file = sys.argv[1]
    cache_file = sys.argv[2]

    log_file = "cacher.log"

    # Initialize log file
    if not os.path.exists(log_file):
        open(log_file, "w").close()

    # Initialize cache
    cache = {}

    # Read cache file if exists
    if os.path.exists(cache_file):
        try:
            with open(cache_file, "r", encoding="utf-8") as f:
                cache_data = json.load(f)
                if isinstance(cache_data, dict):
                    cache = cache_data
                else:
                    cache = {}
        except (json.JSONDecodeError, IOError):
            cache = {}

    # Get current time in seconds
    current_epoch_seconds = time.time()

    # Open log file for appending
    with open(log_file, "a", encoding="utf-8") as log:
        with open(urls_file, "r", encoding="utf-8") as urls:
            failed_urls = 0
            last_retrieval_time = 0

            for line in urls:
                line = line.rstrip()
                if not line:
                    continue

                url = line.strip()

                # Check cache for hit
                cache_hit = False
                cache_entry = cache.get(url)

                if cache_entry and cache_entry["retrieved_at"] >= current_epoch_seconds - 300:
                    cache_hit = True
                    log_entry = {
                        "url": url,
                        "event": "cache_hit",
                        "seconds": time.time() - current_epoch_seconds
                    }
                    log.write(json.dumps(log_entry) + "\n")
                    print(cache_entry["body"])
                else:
                    # Need to fetch
                    # Wait at least 0.5 seconds between retrievals
                    wait_time = max(0.5, last_retrieval_time + 0.5 - current_epoch_seconds)
                    time.sleep(wait_time)

                    try:
                        with urlopen(url, timeout=10) as response:
                            text = response.read().decode("utf-8", errors="ignore")
                            if not text.strip():
                                log_entry = {
                                    "url": url,
                                    "event": "failed",
                                    "seconds": time.time() - current_epoch_seconds
                                }
                                log.write(json.dumps(log_entry) + "\n")
                                print()
                                failed_urls += 1
                            else:
                                cache[url] = {
                                    "retrieved_at": current_epoch_seconds,
                                    "body": text
                                }
                                log_entry = {
                                    "url": url,
                                    "event": "fetched",
                                    "seconds": time.time() - current_epoch_seconds
                                }
                                log.write(json.dumps(log_entry) + "\n")
                                print(text)
                    except (URLError, HTTPError) as e:
                        log_entry = {
                            "url": url,
                            "event": "failed",
                            "seconds": time.time() - current_epoch_seconds
                        }
                        log.write(json.dumps(log_entry) + "\n")
                        print()
                        failed_urls += 1

                # Update last retrieval time
                last_retrieval_time = current_epoch_seconds

                # Write cache to file
                with open(cache_file, "w", encoding="utf-8") as f:
                    json.dump(cache, f, ensure_ascii=False, indent=2)

    # Exit with status 1 if any URL failed, otherwise 0
    if failed_urls > 0:
        sys.exit(1)
    else:
        sys.exit(0)

if __name__ == "__main__":
    main()

