import json
import requests
import time
import threading
from queue import Queue

def evaluate_expression(data, expr):
    try:
        # Use eval with the data variable available
        result = eval(expr, {"data": data})
        return result
    except Exception:
        return "error"

def process_task(task, semaphore):
    url = task["url"]
    expr = task["expr"]

    try:
        response = requests.get(url, timeout=10)
        if response.status_code < 200 or response.status_code > 299:
            return {"url": url, "result": "error"}

        try:
            response_json = response.json()
        except json.JSONDecodeError:
            return {"url": url, "result": "error"}

        result = evaluate_expression(response_json, expr)
        return {"url": url, "result": result}

    except requests.RequestException:
        return {"url": url, "result": "error"}

def main():
    # Read tasks from tasks.json
    with open("tasks.json", "r") as f:
        tasks = json.load(f)

    # Use a semaphore to limit requests to 4 per second
    semaphore = threading.Semaphore(4)

    # Queue to store results
    result_queue = Queue()

    def worker(task):
        with semaphore:
            time.sleep(0.25)  # Ensure we don't exceed 4 requests per second
            result = process_task(task, semaphore)
            result_queue.put(result)

    # Create and start threads for each task
    threads = []
    for task in tasks:
        t = threading.Thread(target=worker, args=(task,))
        t.start()
        threads.append(t)

    # Wait for all threads to complete
    for t in threads:
        t.join()

    # Print results
    while not result_queue.empty():
        result = result_queue.get()
        print(json.dumps(result))

