def main():
    if len(sys.argv) != 3:
        sys.exit(1)

    xml_path = sys.argv[1]
    json_path = sys.argv[2]

    try:
        token_id = sys.stdin.readline().strip()
        service_name = sys.stdin.readline().strip()
    except Exception:
        sys.exit(1)

    if not token_id or not service_name:
        sys.exit(1)

    try:
        tree = ET.parse(xml_path)
        root = tree.getroot()
    except Exception:
        sys.exit(1)

    if root.get('name') is None or root.get('limit') is None:
        sys.exit(1)

    limit = int(root.get('limit'))
    service_name_attr = root.get('name')

    # Check if token ID matches any token element
    token_found = False
    for token_elem in root.findall('.//token'):
        if token_elem.get('id') == token_id:
            token_found = True
            break

    if not token_found:
        print(f"DENY {service_name}")
        sys.exit(0)

    # Check if requested service name matches
    if service_name != service_name_attr:
        print(f"DENY {service_name}")
        sys.exit(0)

    # Process token bucket
    now = time.time()

    try:
        with open(json_path, 'r') as f:
            state = json.load(f)
        tokens = state.get('tokens', 0)
        last_refill = state.get('last_refill', 0)
    except (FileNotFoundError, json.JSONDecodeError):
        tokens = limit
        last_refill = now

    elapsed = now - last_refill
    tokens = min(limit, tokens + elapsed * limit // 60)

    if tokens >= 1:
        print(f"ALLOW {service_name_attr}")
        tokens -= 1
        new_state = {'tokens': tokens, 'last_refill': now}
        with open(json_path, 'w') as f:
            json.dump(new_state, f)
    else:
        print(f"DENY {service_name_attr}")

