def load_text(file_path):
    with open(file_path, 'r') as f:
        return f.read().strip()

def evaluate_expr(expr, attributes):
    try:
        # Replace all occurrences of keys in attributes in the expression
        for key, value in attributes.items():
            expr = expr.replace(f'{{"{key}"}}', str(value))
        # Evaluate the expression
        return eval(expr, {"__builtins__": {}}, {})
    except:
        return False

def compute_signature(payload_str, key_str):
    # Create a hash of the payload string using the key as a salt
    # We use SHA-256 and include the key in the hash
    return hashlib.sha256((payload_str + key_str).encode()).hexdigest()

def main():
    if len(sys.argv) != 4:
        sys.exit(1)

    flags_path = sys.argv[1]
    token_path = sys.argv[2]
