    payload_str = load_text(token_path).splitlines()[0]
    signature_str = load_text(token_path).splitlines()[1]
    key_str = load_text(key_path)

    # Validate signature
    expected_signature = compute_signature(payload_str, key_str)
    if signature_str != expected_signature:
        sys.exit(0)

    # Parse payload
    try:
        payload = json.loads(payload_str)
    except json.JSONDecodeError:
        sys.exit(0)

    # Process flags in order of keys
    for flag_name in flags:
        flag = flags[flag_name]
        if payload.get("role") == flag["role"]:
