import sys
import os
import json
import base64
from Crypto.Cipher import AES
from Crypto.Random import get_random_bytes
from Crypto.Util.Padding import pad, unpad
import xml.etree.ElementTree as ET
import ast

def encrypt(text, passphrase):
    key = passphrase.encode('utf-8')
    cipher = AES.new(key, AES.MODE_CBC)
    ciphertext = cipher.encrypt(pad(text.encode('utf-8'), AES.block_size))
    return base64.b64encode(cipher.iv + ciphertext).decode('utf-8')

def decrypt(encrypted_text, passphrase):
    key = passphrase.encode('utf-8')
    encrypted_data = base64.b64decode(encrypted_text)
    iv = encrypted_data[:16]
    ciphertext = encrypted_data[16:]
    cipher = AES.new(key, AES.MODE_CBC, iv)
    plaintext = unpad(cipher.decrypt(ciphertext), AES.block_size)
    return plaintext.decode('utf-8')

def render_xml(config_file):
    passphrase = os.environ.get('CONFIG_PASSPHRASE')
    if not passphrase:
        raise ValueError("CONFIG_PASSPHRASE environment variable is not set")

    tree = ET.parse(config_file)
    root = tree.getroot()

    settings = {}
    for setting in root.findall('setting'):
        name = setting.get('name')
        value = setting.text
        if not value:
            continue
        decrypted_value = decrypt(value, passphrase)
        if decrypted_value.startswith('{{') and decrypted_value.endswith('}}'):
            expr = decrypted_value[2:-2]
            try:
                resolved_value = ast.literal_eval(expr)
            except (SyntaxError, ValueError):
                resolved_value = expr
        else:
            resolved_value = decrypted_value
        settings[name] = resolved_value

    return json.dumps(settings, indent=2)

def main():
    if len(sys.argv) < 2:
        sys.exit(1)

    action = sys.argv[1]

    if action == 'encrypt':
        if sys.stdin.isatty():
            sys.exit(1)
        text = sys.stdin.read()
        passphrase = os.environ.get('CONFIG_PASSPHRASE')
        if not passphrase:
            sys.exit(1)
        encrypted = encrypt(text, passphrase)
        print(encrypted)

    elif action == 'render':
        if len(sys.argv) != 3:
            sys.exit(1)
        config_file = sys.argv[2]
        if not os.path.exists(config_file):
            sys.exit(1)
        result = render_xml(config_file)
        print(result)

